insert into public.content_translations(division_id,locale_code,field_name,content)
select d.id,s.locale_code,s.field_name,s.content
from seed s join public.divisions d on d.code=s.division_code
on conflict (division_id,locale_code,field_name) where division_id is not null do nothing;

