insert into public.content_translations(business_unit_id,locale_code,field_name,content)
select bu.id,s.locale_code,s.field_name,s.content
from seed s join public.business_units bu on bu.code=s.unit_code
on conflict (business_unit_id,locale_code,field_name) where business_unit_id is not null do nothing;

insert into public.content_translations(category_id,locale_code,field_name,content)
select c.id,l.locale_code,'name',l.content
from public.categories c
cross join (values ('en'::text,'Services'::text),('fr'::text,'Services'::text)) l(locale_code,content)
join public.business_units bu on bu.id=c.business_unit_id
where c.code='services' and bu.code in ('cloud','cybersecurity','software','ai-data','networks','digital','residential-construction','commercial-construction','industrial-construction','civil-engineering','mechanical-engineering','electrical-engineering','structural-engineering','project-management','solar-energy','energy-storage','wind-energy','power-systems','energy-consulting','international-trade','global-sourcing','import-export','supply-chain','business-development')
on conflict (category_id,locale_code,field_name) where category_id is not null do nothing;

