insert into public.services(category_id,code,slug,sort_order,is_active)
select c.id,s.service_code,s.service_slug,s.sort_order,true
from seed s
join public.business_units bu on bu.code=s.unit_code
join public.categories c on c.business_unit_id=bu.id and c.code='services'
on conflict (category_id,code) do nothing;

