insert into public.content_translations(service_id,locale_code,field_name,content)
select svc.id,s.locale_code,'name',s.content
from seed s
join public.business_units bu on bu.code=s.unit_code
join public.categories c on c.business_unit_id=bu.id and c.code='services'
join public.services svc on svc.category_id=c.id and svc.code=s.service_code
on conflict (service_id,locale_code,field_name) where service_id is not null do nothing;

commit;